using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "StarChartOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/StarChart Omen Data")]
public class StarChartOmenData : OmenData
{
	[NonSerialized]
	private Func<bool> omenAction;

	[NonSerialized]
	private OmenInstance omenInstance;

	public override void Initialize(OmenInstance omenInstance)
	{
		this.omenInstance = omenInstance;
		omenAction = delegate
		{
			if (!AlreadyUsed)
			{
				omenInstance.ActivateOmenFeedback();
				ToggleAlreadyUsed(toggle: true);
				return true;
			}
			return false;
		};
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartStartTurnOmens.Add(omenInstance);
		ReferenceSingleton<MiscOmensHandler>.Instance.StarChartAction = omenAction;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.StarChartAction = null;
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartStartTurnOmens.Remove(omenInstance);
	}
}
